local KTool = CS.Engine.Lib.KTool
local StarCount = 3
local ActionDarkDreamStarRoot = Class('ActionDarkDreamStarRoot')

function ActionDarkDreamStarRoot:__init()
    self.starEnv = {}
    self.starData = nil
end

function ActionDarkDreamStarRoot:__delete()
    self.starEnv = nil
    self.starData = nil
end

function ActionDarkDreamStarRoot:Awake()
    self:InitStarEnv()
end

function ActionDarkDreamStarRoot:InitStarEnv()
    self.starEnv = {}
    for i = 1, StarCount do
        local star = self["ActionDarkDreamStar"..i]
        if not isNull(star) then
            local env = CfUtils.GetLuaScr(star,"Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamStarRootCell")
            if not isNull(env) then
                table.insert(self.starEnv,env)
            end
        end
    end
end

function ActionDarkDreamStarRoot:RefreshStarShow(data)
    self.starData = data
    for i, v in pairs(self.starEnv) do
        local isComplete = self:IsComplete(i)
        v:RefreshStarStatus(isComplete)
    end
end

function ActionDarkDreamStarRoot:IsComplete(index)
    for i, v in ipairs(self.starData) do
        if v == index then
            return true
        end
    end
    return false
end

function ActionDarkDreamStarRoot:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActionDarkDreamStarRoot